import{_ as t,o as e,c as s,a2 as o}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"第 12 课：如何写出更好的指令","description":"","frontmatter":{},"headers":[],"relativePath":"modules/module-4/lesson-12.md","filePath":"modules/module-4/lesson-12.md"}'),n={name:"modules/module-4/lesson-12.md"};function l(i,a,d,r,h,p){return e(),s("div",null,[...a[0]||(a[0]=[o(`<h1 id="第-12-课-如何写出更好的指令" tabindex="-1">第 12 课：如何写出更好的指令 <a class="header-anchor" href="#第-12-课-如何写出更好的指令" aria-label="Permalink to &quot;第 12 课：如何写出更好的指令&quot;">​</a></h1><blockquote><p>📌 <strong>学习目标</strong>：掌握编写有效指令的技巧，让 Codex 更准确地理解你的需求<br> ⏱️ <strong>预计时长</strong>：20 分钟<br> 🎯 <strong>本节节奏</strong>：讲解 + 对比示例</p></blockquote><hr><h2 id="一、指令质量决定结果质量" tabindex="-1">一、指令质量决定结果质量 <a class="header-anchor" href="#一、指令质量决定结果质量" aria-label="Permalink to &quot;一、指令质量决定结果质量&quot;">​</a></h2><p>Codex 的能力很强，但它的表现很大程度上取决于你给出的指令。</p><p><strong>好的指令 = 清晰的目标 + 具体的要求 + 明确的验收标准</strong></p><hr><h2 id="二、把大任务拆成小步骤" tabindex="-1">二、把大任务拆成小步骤 <a class="header-anchor" href="#二、把大任务拆成小步骤" aria-label="Permalink to &quot;二、把大任务拆成小步骤&quot;">​</a></h2><h3 id="❌-差的指令-帮我做一个网站" tabindex="-1">❌ 差的指令：&quot;帮我做一个网站&quot; <a class="header-anchor" href="#❌-差的指令-帮我做一个网站" aria-label="Permalink to &quot;❌ 差的指令：&quot;帮我做一个网站&quot;&quot;">​</a></h3><p>这个指令太模糊了。Codex 不知道你想要什么类型的网站、什么风格、包含哪些内容。</p><h3 id="✅-好的指令-帮我做一个个人简介网页" tabindex="-1">✅ 好的指令：&quot;帮我做一个个人简介网页&quot; <a class="header-anchor" href="#✅-好的指令-帮我做一个个人简介网页" aria-label="Permalink to &quot;✅ 好的指令：&quot;帮我做一个个人简介网页&quot;&quot;">​</a></h3><p>好一些，但还是不够具体。</p><h3 id="✅✅-更好的指令" tabindex="-1">✅✅ 更好的指令： <a class="header-anchor" href="#✅✅-更好的指令" aria-label="Permalink to &quot;✅✅ 更好的指令：&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我做一个个人简介网页，要求：</span></span>
<span class="line"><span>1. 包含以下部分：头像、姓名、一句话简介、技能列表、联系方式</span></span>
<span class="line"><span>2. 使用简洁现代的设计风格</span></span>
<span class="line"><span>3. 主色调为蓝色</span></span>
<span class="line"><span>4. 代码保存为 index.html</span></span></code></pre></div><p><strong>关键技巧</strong>：把一个大任务拆成几个小步骤，一步一步来。</p><hr><h2 id="三、告诉-codex-先计划、再执行" tabindex="-1">三、告诉 Codex &quot;先计划、再执行&quot; <a class="header-anchor" href="#三、告诉-codex-先计划、再执行" aria-label="Permalink to &quot;三、告诉 Codex &quot;先计划、再执行&quot;&quot;">​</a></h2><p>有时候，直接让 Codex 执行可能会遗漏细节。更好的做法是：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>在开始之前，先告诉我你的执行计划，等我确认后你再开始</span></span></code></pre></div><p>这样你可以：</p><ul><li>确认 Codex 理解了你的需求</li><li>调整计划中的任何偏差</li><li>避免 Codex 做了一堆无用功</li></ul><hr><h2 id="四、提供背景信息" tabindex="-1">四、提供背景信息 <a class="header-anchor" href="#四、提供背景信息" aria-label="Permalink to &quot;四、提供背景信息&quot;">​</a></h2><p>Codex 不了解你的生活和工作场景，你需要主动提供。</p><h3 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h3><table tabindex="0"><thead><tr><th>场景</th><th>需要提供的背景</th></tr></thead><tbody><tr><td>整理照片</td><td>&quot;这些是我去年去日本旅行拍的照片，按城市分类&quot;</td></tr><tr><td>写邮件</td><td>&quot;这是一封给客户的邮件，语气要正式，主题是关于项目延期&quot;</td></tr><tr><td>数据分析</td><td>&quot;这是我们的销售数据，包含日期、产品、数量、金额四列&quot;</td></tr></tbody></table><blockquote><p>💡 <strong>提示</strong>：背景信息不是越多越好，而是越相关越好。</p></blockquote><hr><h2 id="五、用-验收标准-告诉-codex-什么叫-做好了" tabindex="-1">五、用&quot;验收标准&quot;告诉 Codex 什么叫&quot;做好了&quot; <a class="header-anchor" href="#五、用-验收标准-告诉-codex-什么叫-做好了" aria-label="Permalink to &quot;五、用&quot;验收标准&quot;告诉 Codex 什么叫&quot;做好了&quot;&quot;">​</a></h2><h3 id="示例-1" tabindex="-1">示例 <a class="header-anchor" href="#示例-1" aria-label="Permalink to &quot;示例&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我整理这份文档，要求：</span></span>
<span class="line"><span>1. 去除所有空行</span></span>
<span class="line"><span>2. 统一标题格式（一级标题用 #，二级标题用 ##）</span></span>
<span class="line"><span>3. 检查并修正错别字</span></span>
<span class="line"><span>4. 最后告诉我你做了哪些修改</span></span></code></pre></div><p>注意最后一条——<strong>让 Codex 告诉你它做了什么</strong>，这样你可以快速验证结果是否符合预期。</p><hr><h2 id="六、指令模板" tabindex="-1">六、指令模板 <a class="header-anchor" href="#六、指令模板" aria-label="Permalink to &quot;六、指令模板&quot;">​</a></h2><h3 id="文件操作类" tabindex="-1">文件操作类 <a class="header-anchor" href="#文件操作类" aria-label="Permalink to &quot;文件操作类&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请帮我 [动作] [对象]，[具体要求]，[验收标准]</span></span></code></pre></div><h3 id="内容生成类" tabindex="-1">内容生成类 <a class="header-anchor" href="#内容生成类" aria-label="Permalink to &quot;内容生成类&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请帮我 [动作] 一个 [类型]，关于 [主题]，要求 [格式/风格]，[验收标准]</span></span></code></pre></div><h3 id="数据分析类" tabindex="-1">数据分析类 <a class="header-anchor" href="#数据分析类" aria-label="Permalink to &quot;数据分析类&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请帮我分析 [数据源]，找出 [关注点]，输出 [格式]，[验收标准]</span></span></code></pre></div><hr><h2 id="七、本节实操任务" tabindex="-1">七、本节实操任务 <a class="header-anchor" href="#七、本节实操任务" aria-label="Permalink to &quot;七、本节实操任务&quot;">​</a></h2><ol><li>选择一个你想让 Codex 完成的任务</li><li>先用模糊的指令试一次</li><li>再用清晰的指令（按照上面的模板）试一次</li><li>对比两次结果的差异</li></ol><hr><h2 id="八、本节小结" tabindex="-1">八、本节小结 <a class="header-anchor" href="#八、本节小结" aria-label="Permalink to &quot;八、本节小结&quot;">​</a></h2><table tabindex="0"><thead><tr><th>技巧</th><th>说明</th></tr></thead><tbody><tr><td>拆分任务</td><td>大任务拆成小步骤，逐步完成</td></tr><tr><td>先计划后执行</td><td>让 Codex 先给出计划，确认后再执行</td></tr><tr><td>提供背景</td><td>主动告诉 Codex 相关上下文</td></tr><tr><td>验收标准</td><td>明确告诉 Codex 什么叫&quot;做好了&quot;</td></tr></tbody></table><hr><h2 id="九、下一步" tabindex="-1">九、下一步 <a class="header-anchor" href="#九、下一步" aria-label="Permalink to &quot;九、下一步&quot;">​</a></h2><p><a href="./lesson-13.html">→ 第 13 课：安全与权限管理</a></p>`,49)])])}const b=t(n,[["render",l]]);export{u as __pageData,b as default};
